import { createAI } from './ai.js';
const icons={leaf:'<path d="M20 4c-8-2-16 3-14 10 1 5 9 7 12 0 2-4 2-10 2-10Z"/><path d="M4 21 15 10M8 16l-1-5m5 1 5 1"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',folder:'<path d="M3 7V5h6l2 2h10v13H3Z"/>',book:'<path d="M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1Zm0 0v15"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',down:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1.5"/><path d="m3 17 6-6 4 4 3-3 5 5"/>',sliders:'<path d="M4 7h6m4 0h6M4 17h10m4 0h2"/><circle cx="12" cy="7" r="2"/><circle cx="16" cy="17" r="2"/>',shield:'<path d="m12 2 8 3v6c0 5-8 11-8 11S4 16 4 11V5Z"/><path d="m8 11 3 3 5-6"/>',file:'<path d="M5 2h9l5 5v15H5ZM14 2v6h5M8 13h8M8 17h6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',expand:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="1"/><path d="M16 8V3H3v13h5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/>'};
const icon=(n)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.file}</svg>`;
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=()=>crypto.randomUUID();
const date=()=>new Date().toISOString();
let TYPES=[];
const colors=[{id:'alder',name:'Вільха',hex:'#916634'},{id:'black',name:'Чорна',hex:'#2A2725'},{id:'chestnut',name:'Каштан',hex:'#603A2D'},{id:'clear',name:'Чистий',hex:'#BAA687'},{id:'mahogany',name:'Махагоні',hex:'#612F32'},{id:'pine',name:'Сосна',hex:'#C19F42'},{id:'stained-oak',name:'Морений дуб',hex:'#704F2B'},{id:'walnut',name:'Горіх',hex:'#9E805D'}];
const schemes=[['clear','mahogany','pine'],['clear','alder','black'],['clear','pine','black'],['clear','chestnut','pine']];
const kinds={magnolia:{name:'Магнолія',type:'Шкатулка',width:160,height:120,parts:'9',palette:schemes[0],brief:'Шкатулка з великою магнолією. Природні пропорції, широкі пелюстки, мінімум дрібних деталей.',note:'Верхня пелюстка близька до рамки: відступ варто збільшити в кресленні.',approved:true},tits:{name:'Дві синиці',type:'Ключниця',width:200,height:140,parts:'13–15',palette:schemes[2],brief:'Овальна ключниця: дві синиці на гілці, повернуті одна до одної. Три металеві гачки внизу.',note:'Потрібно уточнити кількість деталей і кріплення під реальну фурнітуру.',approved:false},bird:{name:'Птах у колі',type:'Підставка',width:100,height:100,parts:'4',palette:schemes[1],brief:'Кругла підставка з птахом у профіль, гравійованими лапками та круговим обрамленням.',note:'Історичний орієнтир. Повторно перевірте відблиск ока та гравіювання лапок за актуальними правилами.',approved:true}};
function seed(key){const k=kinds[key];return {id:id(),title:k.name,type:k.type,width:k.width,height:k.height,brief:k.brief,palette:[...k.palette],frame:'engraved',layers:2,pendingAssetsUpdate:[],reference:null,concepts:[],selected:null,prepared:true,assets:{preview:`assets/${key}-preview.png`,master:`assets/${key}-master.png`},notes:[],locks:[],reviews:{engraving:'unknown',palette:'unknown',parts:'unknown',composition:'unknown'},versions:[],approved:false,example:key,createdAt:date(),updatedAt:date()};}
let db=null,state={projects:[],active:null},page='studio',view='preview',filter='all',search='',knowledgeTab='overview',knowledgeText='',saving=false;
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
async function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('plywood-flow-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('app');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function readDB(){return new Promise((resolve,reject)=>{const tx=db.transaction('app');const req=tx.objectStore('app').get('state');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function persist(){state.schemaVersion=STATE_VERSION;for(const p of state.projects)ensureRoute(p);if(!db)return;try{await writeAppState(db,state);}catch(e){toast('Не вдалося зберегти у браузері. Експортуйте проєкт у JSON.');}}
function current(){return state.projects.find(x=>x.id===state.active);}
function markOutdated(p){invalidateApproval(p);p.aiReport=null;if(p.assets.preview||p.assets.master)p.pendingAssetsUpdate=['preview','master'];}
async function editableProject(p,{mode='parameters',checkpoint=true}={}){
  if(mustForkForChange(p))return addVariant(p,mode);
  if(checkpoint&&needsSourceCheckpoint(p))await snapshot(p,false,'Перед зміною параметрів виробу');
  return p;
}
async function addVariant(p,mode='parameters'){
  const child=createVariant(p,state.projects,{mode});state.projects.unshift(child);state.active=child.id;page='studio';view=child.assets.preview?'preview':'master';await persist();render();toast('Створено окремий варіант. Вихідний виріб збережено.');return child;
}
function sourceChanged(p){markSourceChanged(p);markOutdated(p);touch(p);}
async function confirmGeneration(p){
  if(!p.conceptSetOutdated&&!p.pendingAssetsUpdate?.length)return true;
  const signature=await generationBasis(p);if(p.conceptReuseConfirmation?.signature===signature)return true;
  return new Promise(resolve=>{
    let settled=false;const finish=ok=>{if(settled)return;settled=true;dialog.removeEventListener('close',cancel);dialog.removeEventListener('cancel',cancel);resolve(ok);};const cancel=()=>{if(!dialog.open)finish(false);};
    modal(`<h2>Створити зображення за оновленим завданням?</h2><p>Збережені концепції та зображення могли бути створені за попередніми параметрами. Використаємо поточний задум, розміри й обрану концепцію.</p><p><strong>${esc(p.type)} · ${p.width} × ${p.height} мм</strong><br>${esc(p.brief)}</p><p>Доступні морилки: ${p.palette.map(k=>esc(colors.find(c=>c.id===k)?.name||k)).join(' · ')}. Для обраної концепції використаємо її поєднання цих кольорів.</p><p class="hint">Попередні зображення залишаться доступними до нового результату та збережуться у версіях.</p><div class="dialog-actions"><button class="btn" data-action="close">Повернутися</button><button class="btn primary" id="confirm-generation">Створити зображення</button></div>`);
    dialog.addEventListener('close',cancel);dialog.addEventListener('cancel',cancel);
    document.querySelector('#confirm-generation').onclick=async()=>{if(current()!==p||await generationBasis(p)!==signature){finish(false);close();return;}p.conceptReuseConfirmation={signature,at:date()};await persist();finish(true);close();};
  });
}
function touch(p){p.updatedAt=date();invalidateApproval(p);persist();}
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',4500);}
const btn=(action,text,ic,cl='')=>`<button class="btn ${cl}" data-action="${action}">${ic?icon(ic):''}${text}</button>`;
function header(){return `<aside class="sidebar"><div class="brand"><div class="brandmark">${icon('leaf')}</div><div>Plywood<span style="font-weight:400"> Flow</span><small>МАЙСТЕРНЯ ІДЕЙ</small></div></div><nav class="nav" aria-label="Головна навігація">${[['studio','sliders','Майстерня'],['projects','folder','Мої проєкти'],['knowledge','book','База знань'],['types','grid','Типи виробів']].map(([key,ic,title])=>`<button data-page="${key}" aria-label="${title}" class="${page===key?'active':''}">${icon(ic)}<span>${title}</span>${key==='projects'?`<span class="count">${state.projects.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="overline">ВАШ МАТЕРІАЛ</div><div class="material"><div class="ply"></div><div>Фанера 3 мм<div class="muted" style="font-size:10px">Лист 300 × 400 мм</div></div></div><p>Від першої ідеї<br>до виробу, який хочеться створити.</p><div class="badge green">${icon('lock')}Приватний простір</div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Майстерня <span>/</span><strong>${page==='projects'?'Мої проєкти':page==='knowledge'?'База знань':page==='types'?'Типи виробів':esc(current()?.title||'Новий проєкт')}</strong></div><div class="top-actions"><span class="badge">Codex SDK · локальна майстерня</span><div class="avatar">В</div></div></header>`;}
function render(){app.innerHTML=`<div class="shell ${page==='studio'?'studio-shell':''}">${header()}<div class="page">${page==='studio'?studio():page==='projects'?projects():page==='types'?typeCatalog.page():knowledge()}</div></main></div>`;if(page==='knowledge')loadKnowledge();}
const routeHints=ROUTE_HINTS;
function refreshProjectContext(){
  const p=current(),stage=document.querySelector('.project-stage');if(!p)return;
  if(stage&&stage.dataset.currentStep!==projectRoute(p).current){render();return;}
  const inspector=document.querySelector('#result-inspector-content');
  if(inspector){const next=resultInspector(p,{esc,...ai.resultContext()});if(inspector._plywoodHTML!==next){const expanded=[...inspector.querySelectorAll('details')].map(el=>el.open);inspector.innerHTML=next;inspector._plywoodHTML=next;inspector.querySelectorAll('details').forEach((el,i)=>el.open=expanded[i]||false);}}
  const mobile=document.querySelector('.result-mobile-actions');if(mobile){const next=resultActions(p,{esc});if(mobile._plywoodHTML!==next){mobile.innerHTML=next;mobile._plywoodHTML=next;}}
  const summary=document.querySelector('#project-context-content');if(summary){const next=projectSummary(p,{esc,colors});if(summary._plywoodHTML!==next){summary.innerHTML=next;summary._plywoodHTML=next;}}
  const nav=document.querySelector('.project-route .route-steps');if(nav){const next=routeNavigation(p,esc);if(nav._plywoodHTML!==next){nav.outerHTML=next;document.querySelector('.project-route .route-steps')._plywoodHTML=next;}}
  const heading=document.querySelector('.project-stage-heading');if(heading){const next=projectStageHeading(p,esc);if(heading._plywoodHTML!==next){heading.innerHTML=next;heading._plywoodHTML=next;}}
}

function routeContent(p){
  const step=ensureRoute(p);
  if(step==='concepts')return p.concepts.length?conceptScreen(p,{esc,colors}):emptyConceptScreen(p,{launching:ai.isLaunching(p)});
  if(step==='generation')return ai.generation(p);
  if(step==='saved')return savedScreen(p,{esc,icon,safeImage,view,colors,versions:versionList(p)});
  if(step==='result')return result(p);
  return step==='palette'?paletteSettings(p):briefSettings(p);
}

function studio(){
  const p=current();if(!p)return `<div class="empty"><h1>Почнімо з ідеї</h1>${btn('new','Створити проєкт','plus','primary')}</div>`;
  ensureRoute(p);
  return `<div class="heading project-heading"><div><div class="overline" style="margin-bottom:7px">ВАШ ТВОРЧИЙ ПРОЦЕС</div><h1>${esc(p.title)}</h1><p>${p.example?'Збережений приклад із нашої майстерні.':'Від короткого задуму до погодженого виробу.'}</p></div><div class="actions-wrap">${btn('new','Новий проєкт','plus')}${!['result','saved'].includes(projectRoute(p).current)?btn('save','Зберегти версію','folder'):''}</div></div>${projectRoute(p).current==='saved'&&!p.variantOf?'':variantNotice(p,{esc,parentExists:state.projects.some(x=>x.id===p.variantOf?.projectId)})}${projectShell(p,{esc,colors,content:routeContent(p),aiPanel:ai.panel(p),showContext:projectRoute(p).current!=='saved',inspector:projectRoute(p).current==='result'?resultInspector(p,{esc,...ai.resultContext()}):'',collapsed:window.matchMedia('(max-width: 1000px)').matches})}<div class="footer-note">Plywood Flow · Зображення — орієнтир для ручної підготовки креслень</div>`;
}

function briefSettings(p){return `<div class="panel brief-settings"><h3>Задум і конструкція</h3><div class="form-grid"><div class="field"><label for="product-type">Тип виробу</label><select id="product-type" data-field="type">${TYPES.map(t=>`<option ${p.type===t?'selected':''}>${esc(t)}</option>`).join('')}</select></div>${typeCatalog.fields(p)}</div><div class="field"><label for="brief">Ваш задум</label><textarea id="brief" data-field="brief" maxlength="4000" placeholder="Опишіть сюжет і бажаний вигляд виробу…">${esc(p.brief)}</textarea></div><div class="form-grid"><div class="field"><label>Габарити декору, мм</label><div class="dimensions"><input aria-label="Ширина, мм" type="number" min="20" max="400" value="${p.width}" data-field="width"><span>×</span><input aria-label="Висота, мм" type="number" min="20" max="400" value="${p.height}" data-field="height"></div><p class="hint">Плоска деталь має вміщуватися на листі 300 × 400 мм.</p></div><div class="field"><label for="layers">Конструкція декору</label><select id="layers" data-field="layers"><option value="2" ${p.layers!==1?'selected':''}>Підкладка + інкрустація</option><option value="1" ${p.layers===1?'selected':''}>Один шар, без інкрустації</option></select></div></div><details class="project-extra"><summary>Референс (необов’язково)${p.reference?' · додано':''}</summary><label class="reference-drop">${p.reference?`<img class="thumb" src="${safeImage(p.reference)}" alt="Ваш референс">`:icon('upload')}<span>${p.reference?'Замінити референс':'Додати референс'}</span><input type="file" accept="image/png,image/jpeg,image/webp" data-upload="reference"></label>${p.reference?btn('remove-reference','Прибрати референс',null,'tiny'):''}<p class="hint">PNG, JPG або WebP до 8 МБ. Система адаптує зображення до технології.</p></details></div><div class="project-next">${btn('route-palette','Далі: палітра','arrow','primary')}</div>`;}
function paletteSettings(p){const working=['running','queued'].includes(p.aiJob?.status);return `<div class="panel palette-settings"><h3>Які морилки можна використати?</h3><p class="palette-description">Оберіть доступні кольори. Система сама запропонує їх гармонійні поєднання для кожної концепції.</p><div class="palette-options">${colors.map(c=>`<button type="button" class="palette-option ${p.palette.includes(c.id)?'selected':''}" data-color="${c.id}" aria-pressed="${p.palette.includes(c.id)}" ${working?'disabled':''}><span class="palette-sample" style="background:${c.hex}"></span><span>${esc(c.name)}</span><span aria-hidden="true">${p.palette.includes(c.id)?'✓':''}</span></button>`).join('')}</div><p class="hint">${p.layers===1?'Для одного шару оберіть одне оздоблення. Натискання іншого кольору замінить попередній.':'До 3 оздоблень; четвертим може бути лише «Чорна».'} «Чистий» — фанера без морилки.</p><div class="divider"></div><div class="field"><label for="frame">Обрамлення</label><select id="frame" data-field="frame" ${working?'disabled':''}><option value="engraved" ${p.frame==='engraved'?'selected':''}>Гравійована обводка</option><option value="cut" ${p.frame==='cut'?'selected':''} ${p.layers===1?'disabled':''}>Окрема фарбована рамка ≥ 2 мм</option><option value="none" ${p.frame==='none'?'selected':''}>Без рамки</option></select></div><details class="project-extra"><summary>Вимоги, які враховуються автоматично</summary><ul class="production-rules"><li>Фанера 3 мм, лист 300 × 400 мм.</li><li>Перемички й вирізані рамки — від 2 мм.</li><li>Один колір на фізичну деталь, без змішування морилок.</li><li>Гравіювання й кромки лише чорні; світле гравіювання не допускається.</li><li>Бажано до 15 деталей, з урахуванням розміру й сюжету.</li><li>Композиція, перекривання об’єктів і деталізація мають відповідати конструкції.</li></ul></details></div><p class="hint">Запускаючи створення концепцій, ви підтверджуєте показану палітру. Зображення створюватимемо після вибору концепції.</p><div class="palette-step-actions"><button class="btn" data-step="brief">Назад: задум</button><button class="btn primary" data-action="palette-concepts" ${working?'disabled':''}>${working?'Завдання виконується…':p.concepts.length?'Створити нові 10 концепцій':'Створити 10 концепцій'}${icon('arrow')}</button></div>${p.concepts.length?'<button class="btn full" data-step="concepts" style="margin-top:12px">Повернутися до збережених концепцій</button>':''}`;}

function result(p){return resultScreen(p,{esc,icon,safeImage,view,versions:versionList(p),manualReview:manualReview(p),technical:technicalFiles(p)});}
function manualReview(p){return `<div class="panel"><h3>Ваша оцінка</h3><p class="hint">Необов’язкові власні позначки. Вони не змінюють звіт ШІ. Позначка «Потрібна правка» блокує прийняття, поки ви її не переглянете.</p>${[['engraving','Чорне гравіювання'],['palette','Відповідність палітрі'],['parts','Поділ на деталі'],['composition','Цілісність композиції']].map(([k,t])=>`<div class="review-item"><span>${t}</span><select data-review="${k}" aria-label="${t}">${[['unknown','Не перевірено'],['pass','Прийнятно'],['fail','Потрібна правка']].map(([v,l])=>`<option value="${v}" ${p.reviews[k]===v?'selected':''}>${l}</option>`).join('')}</select></div>`).join('')}<p class="hint">Геометрію, ширини від 2 мм і кріплення перевіряють у SolidWorks.</p></div>`;}
function technicalFiles(p){return `<div class="lower-grid">${['preview','master'].map(k=>`<div class="file-card"><div><strong>${k==='preview'?'Вигляд виробу':'Фронтальний декор'}</strong></div><button class="iconbtn" data-download="${k}" aria-label="Завантажити ${k==='preview'?'вигляд виробу':'декор'}" ${!p.assets[k]?'disabled':''}>${icon('down')}</button></div>`).join('')}</div><div class="actions-wrap" style="margin-top:12px">${['preview','master'].map(k=>`<label class="btn tiny">${icon('upload')}${k==='preview'?'Додати вигляд':'Додати декор'}<input type="file" hidden data-upload="${k}" accept="image/png,image/jpeg,image/webp"></label>`).join('')}${btn('prompt','Завдання і промпт','file','tiny')}${btn('export','Експорт JSON','down','tiny')}</div>${p.aiData?`<details class="ai-details"><summary>План, промпти та відомості про запуск</summary><pre>${esc(JSON.stringify({plan:p.aiData.plan,prompts:p.aiData.prompts,knowledge:p.aiData.knowledge},null,2))}</pre></details>`:''}`;}

function projects(){const list=state.projects.filter(p=>(filter==='all'||(filter==='approved'?p.approved:!p.approved))&&`${p.title} ${p.type}`.toLowerCase().includes(search.toLowerCase()));return `<div class="heading"><div><div class="overline" style="margin-bottom:7px">ВАША КОЛЕКЦІЯ</div><h1>Мої проєкти</h1><p>Ідеї, які можна зберегти, допрацювати й повторити.</p></div>${btn('new','Новий проєкт','plus','primary')}</div><div class="onboard">${icon('leaf')}<div><strong>Маленька майстерня великих задумів</strong><p>Три приклади вже тут. Створіть свій перший проєкт або продовжте один із них.</p></div>${btn('import','Імпорт JSON','upload')}</div><div class="toolbar-row"><div class="filter">${[['all','Усі'],['draft','Чернетки'],['approved','Погоджені']].map(([v,t])=>`<button data-filter="${v}" class="${filter===v?'active':''}">${t}</button>`).join('')}</div><input id="search" class="search" placeholder="Знайти проєкт…" aria-label="Знайти проєкт" value="${esc(search)}"></div><div class="projects-grid">${list.map(p=>`<article class="project-card">${p.assets.preview?`<img class="cover" src="${safeImage(p.assets.preview)}" alt="${esc(p.title)}">`:`<div class="no-image">${icon('image')}</div>`}<div class="body"><span class="badge ${p.approved?'green':''}">${p.approved?'Погоджено вами':p.example?'Приклад':'Чернетка'}</span><h3>${esc(p.title)}</h3>${p.variantOf?`<p class="hint">Варіант · з «${esc(p.variantOf.title)}»</p>`:''}<p>${esc(p.type)} · ${p.width} × ${p.height} мм · ${p.palette.length} кольори</p><div class="card-actions"><button class="btn tiny" data-open="${p.id}">Відкрити ${icon('arrow')}</button><button class="iconbtn danger" data-delete="${p.id}" aria-label="Видалити ${esc(p.title)}">${icon('trash')}</button></div></div></article>`).join('')||'<div class="panel"><p>Проєктів за цим запитом немає.</p></div>'}</div><p class="preview-hint">Зберігання — у цьому браузері. Для резервної копії експортуйте проєкт у JSON. Файли автоматично не синхронізуються між пристроями.</p>`;}
const kb={overview:['Огляд бази','README.md'],tech:['Технічні вимоги','01-технічні-вимоги.md'],design:['Правила дизайну','02-дизайн.md'],palette:['Палітра','палітра/README.md'],engraving:['Гравіювання','технології/гравіювання.md'],cut:['Різання й інкрустація','технології/різання-та-інкрустація.md'],review:['Перевірка','03-перевірка.md'],unknown:['Відкриті питання','04-відкриті-питання.md']};
function knowledge(){return `<div class="heading"><div><div class="overline" style="margin-bottom:7px">ОПОРА ДЛЯ КОЖНОЇ ІДЕЇ</div><h1>База знань</h1><p>Технологія, композиція й досвід нашої майстерні. Версія 1.0.</p></div><a class="btn" href="knowledge/README.md" download>${icon('down')}Огляд Markdown</a></div><div class="knowledge-layout"><aside class="panel knowledge-nav">${Object.entries(kb).map(([k,[t]])=>`<button data-kb="${k}" class="${knowledgeTab===k?'active':''}">${t}</button>`).join('')}</aside><article class="panel article">${knowledgeTab==='palette'?`<div class="knowledge-palette">${colors.map(c=>`<div class="color-card"><div class="paint" style="background:${c.hex}"></div><p><strong>${c.name}</strong><br><span class="mono muted">${c.hex}</span></p></div>`).join('')}</div>`:''}<div id="kb-content"><p class="muted">Завантажуємо документ…</p></div></article></div>`;}
async function loadKnowledge(){const tab=knowledgeTab;try{const r=await fetch(`knowledge/${kb[tab][1]}`);if(!r.ok)throw Error();const t=await r.text();if(page==='knowledge'&&tab===knowledgeTab)document.querySelector('#kb-content').innerHTML=`<pre>${esc(t)}</pre>`;}catch{const el=document.querySelector('#kb-content');if(el)el.textContent='Документ недоступний. Спробуйте оновити сторінку.';}}
function safeImage(s){return typeof s==='string'&&(/^(assets\/(magnolia|tits|bird)-(preview|master)\.png)$/.test(s)||/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(s))?s:'';}
function validateForm(p){if(!p.brief.trim()){toast('Додайте короткий опис задуму.');return false;}if(!Number.isFinite(p.width)||!Number.isFinite(p.height)||p.width<20||p.height<20||!((p.width<=300&&p.height<=400)||(p.width<=400&&p.height<=300))){toast('Задайте розміри від 20 мм, що вміщуються на листі 300 × 400 мм.');return false;}if(p.layers===1&&(p.palette.length!==1||p.frame==='cut')){toast('Без інкрустації потрібне одне оздоблення та гравійована рамка або без рамки.');return false;}if(!p.palette.length){toast('Оберіть хоча б одне оздоблення.');return false;}return true;}
function prompt(p){const c=p.concepts.find(c=>c.id===p.selected);return `ПРОЄКТ: ${p.title}\nТип виробу: ${p.type}. Декор ${p.width} × ${p.height} мм.\nЗАДУМ: ${p.brief}\nКОНЦЕПЦІЯ: ${c?`${c.title}. ${c.description}`:'Збережений приклад або власний задум.'}\n\nМАТЕРІАЛ І ТЕХНОЛОГІЯ\nФанера 3 мм, лист 300 × 400 мм. ${p.layers===1?'Один шар без інкрустації, одне оздоблення всієї деталі; зображення передається чорним гравіюванням.':'Підкладка та один спільний верхній шар інкрустації; без випадкового рельєфу.'} Один колір на фізичну деталь, без змішування морилок. Суміжні вставки мають спільний різ, без додаткового зазору. Перемички не менше 2 мм; точні розміри перевіряються після обведення у SolidWorks. Бажано до 15 деталей із фоном і рамкою.\n\nПАЛІТРА\n${p.palette.map(k=>{const c=colors.find(x=>x.id===k);return `${c.id}: ${c.name} ${c.hex}`;}).join('\n')}\n«Чистий» — натуральна фанера, не біла фарба. Гравіювання лише ЧОРНЕ. На чорних частинах НЕ додавати світлі риски, обідки чи відблиски як гравіювання. Кромки чорні.\n\nКОМПОЗИЦІЯ\nОдин головний мотив, узгоджені пропорції, баланс темних мас, достатні відступи, без випадкових дотиків. ${p.layers===1?'Чорне гравійоване обрамлення або без рамки, без окремих вставок.':p.frame==='cut'?'Обрамлення — окрема вирізана рамка, ширина всюди ≥2 мм, один колір із палітри, та сама площина інкрустації.':p.frame==='engraved'?'Обрамлення — тонка ЧОРНА гравійована лінія, не окрема вставка.':'Свідомо відкрита композиція без рамки.'}\n${COMPOSITION_GUIDANCE}\n\nРЕЗУЛЬТАТИ\n1. ${MASTER_VIEW_GUIDANCE}\n2. Вигляд усього виробу за тим самим декором. Не змінювати форму, кількість і кольори деталей між видами.\n${p.reference?'Є завантажений референс: долучити окремим зображенням, зберегти головні ознаки й композицію.':''}\nЗБЕРЕГТИ: ${p.locks.join('; ')||'погоджені рішення після їх визначення'}.\nПРАВКИ: ${p.notes.join('; ')||'немає'}.\n\nПЕРЕВІРКА\nПеревірити фактичні зображення: взаємодію мотивів, просторові плани там, де доречно, переривання перекритих контурів і змістове чорне гравіювання; палітру, чорне гравіювання, відсутність зайвих шарів і крихких вставок, відповідність обох видів. Не оголошувати растр готовим до різання. Невиміряні ширини позначити як ручну перевірку.\n\n${typeCatalog.prompt(p)}\n\nБаза знань v1.0. Цей текст описує завдання; фактичний стан генерації та перевірки дивіться в панелі ШІ.`;}
function modal(content){dialog.innerHTML=content;dialog.showModal();}
function close(){dialog.close();}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function exportProject(p){
  const copy=structuredClone(p),cache=new Map();
  async function embed(src){if(!src||src.startsWith('data:'))return src;if(cache.has(src))return cache.get(src);const response=await fetch(src);if(!response.ok)throw Error('asset');const blob=await response.blob();const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob);});cache.set(src,data);return data;}
  for(const item of [copy,...copy.versions.map(v=>v.data)]){for(const k of ['preview','master'])if(item.assets[k])item.assets[k]=await embed(item.assets[k]);if(item.reference)item.reference=await embed(item.reference);}
  download('plywood-flow-project.json',JSON.stringify({format:'plywood-flow-project',version:1,project:copy},null,2));toast('Експортовано проєкт із вкладеними зображеннями та версіями');
}
function openNew(){modal(`<div class="dialog-head"><h2>Що створимо цього разу?</h2><button data-action="close" class="iconbtn" aria-label="Закрити">${icon('close')}</button></div><form id="new-form"><div class="field"><label for="new-title">Назва проєкту</label><input id="new-title" name="title" required maxlength="100" placeholder="Наприклад: Лис у лісі" autofocus></div><div class="form-grid"><div class="field"><label for="new-type">Тип виробу</label><select id="new-type" name="type">${TYPES.map(t=>`<option>${esc(t)}</option>`).join('')}</select></div><div class="field"><label>Розміри декору, мм</label><div class="dimensions"><input aria-label="Ширина нового декору" name="width" type="number" min="20" max="400" value="160" required><span>×</span><input aria-label="Висота нового декору" name="height" type="number" min="20" max="400" value="120" required></div></div></div><div class="field"><label for="new-brief">Короткий задум</label><textarea id="new-brief" name="brief" required maxlength="4000" placeholder="Опишіть сюжет і те, що для вас важливо…"></textarea></div><div class="note soft">Концепції, генерація та перевірка запускаються окремими кнопками через локальний Codex SDK.</div><div class="dialog-actions"><button class="btn" type="button" data-action="close">Скасувати</button><button class="btn primary" type="submit">Створити проєкт ${icon('arrow')}</button></div></form>`);}
async function handle(action){let p=current();if(action==='variant'){await addVariant(p);return;}if(action==='variant-concepts'){await addVariant(p,'concepts');return;}if(action==='palette-edit'){p=await editableProject(p);return paletteConfirmation.ensure(p,{force:true,launch:false});}if(action.startsWith('catalog-'))return typeCatalog.action(action);if(action.startsWith('ai-'))return ai.action(action.slice(3));switch(action){case'new':openNew();break;case'close':close();break;case'import':document.querySelector('#import-file').click();break;case'remove-reference':p=await editableProject(p);p.reference=null;sourceChanged(p);render();break;case'palette-concepts':{if(projectRoute(p).current!=='palette'||!validateForm(p)||['running','queued'].includes(p.aiJob?.status))return;const launch=document.querySelector('[data-action="palette-concepts"]');if(launch?.disabled)return;if(launch)launch.disabled=true;try{p=await editableProject(p,{checkpoint:false});await paletteConfirmation.confirmCurrent(p);await handle('concepts');}finally{if(launch?.isConnected)launch.disabled=false;}break;}case'concepts':if(!validateForm(p))return;if(p.concepts.length||p.assets.preview||p.assets.master){modal(`<h2>Створити новий набір із 10 концепцій?</h2><p>Поточний набір буде замінено після успішної генерації. Перед застосуванням нового набору поточний стан автоматично збережеться у версіях. Зображення залишаться доступними.</p><div class="dialog-actions">${btn('close','Скасувати')}${btn('do-concepts','Продовжити','arrow','primary')}</div>`);}else await makeConcepts(p);break;case'do-concepts':close();await makeConcepts(p);break;case'route-palette':if(!briefIsReady(p)){toast('Додайте задум, тип і габарити від 20 мм у межах листа 300 × 400 мм.');return;}if(!moveToRoute(p,'palette')){toast(routeHints.palette);return;}await persist();render();break;case'back-brief':moveToRoute(p,'brief');await persist();render();break;case'prepare':case'generate-concept':{const issue=conceptIssue(p,p.concepts.find(c=>c.id===p.selected));if(issue){toast(issue);return;}if(!validateForm(p))return;await ai.start('generate');break;}case'save':saveVersionDialog(p);break;case'prompt':modal(`<div class="dialog-head"><h2>Завдання для генерації</h2><button class="iconbtn" data-action="close" aria-label="Закрити">${icon('close')}</button></div><p class="hint">Завдання буде доповнене базою знань і планом деталей під час запуску ШІ. Його також можна використати вручну.</p><textarea class="prompt" id="prompt-text" readonly>${esc(prompt(p))}</textarea><div class="dialog-actions">${btn('copy-prompt','Копіювати','copy')}${btn('download-prompt','Завантажити TXT','down','primary')}</div>`);break;case'copy-prompt':try{await navigator.clipboard.writeText(prompt(p));toast('Завдання скопійовано');}catch{document.querySelector('#prompt-text').select();toast('Виділіть і скопіюйте текст вручну');}break;case'download-prompt':download('plywood-task.txt',prompt(p),'text/plain;charset=utf-8');break;case'passport':download('plywood-product-passport.txt',passportText(p,colors),'text/plain;charset=utf-8');break;case'export':await exportProject(p); break;case'add-note':{const n=document.querySelector('#change-note').value.trim();if(!n)return;await snapshot(p,false,'Перед додаванням правки');p.notes.push(n.slice(0,4000));markOutdated(p);touch(p);render();toast('Правку додано до завдання. Зображення не змінювалося.');break;}case'open-corrections':{const editor=document.querySelector('#result-corrections');if(editor){editor.open=true;p.resultDraft={...p.resultDraft,open:true};await persist();editor.scrollIntoView({block:'center'});document.querySelector('#change-note')?.focus({preventScroll:true});}break;}case'apply-result-edit':{if(['running','queued'].includes(p.aiJob?.status)||!p.assets.master){toast('Дочекайтеся завершення завдання або додайте декор.');return;}let notes;try{notes=revisionNotes(p,document.querySelector('#change-note')?.value,document.querySelector('#use-ai-findings')?.checked);}catch(error){toast(error.message);return;}p=await editableProject(p,{checkpoint:false});if(JSON.stringify(notes)!==JSON.stringify(p.notes)){await snapshot(p,false,'Перед застосуванням нових правок');p.notes=notes;markOutdated(p);touch(p);}const started=await ai.start('edit');if(started){p.resultDraft={text:'',includeFindings:false,open:false};await persist();}break;}case'approve':await appearanceApproval.open(p);break;case'expand':if(p.assets[view])modal(`<div class="dialog-head"><h2>${esc(p.title)}</h2><button class="iconbtn" data-action="close" aria-label="Закрити">${icon('close')}</button></div><img src="${safeImage(p.assets[view])}" alt="Збільшене зображення" style="width:100%;max-height:75vh;object-fit:contain">`);break;}}
async function makeConcepts(p){await ai.start('concepts');}
function versionConcept(v){return v.data.concepts?.find(c=>c.id===v.data.selected)?.title||null;}
function versionLabel(v){return v.label||versionConcept(v)||(v.data.approved?'Погоджений вигляд':v.data.assets?.preview?'Збережений вигляд':v.data.title||'Збережений задум');}
function versionTime(v){return new Date(v.savedAt).toLocaleString('uk-UA',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit'});}
function ensureVersions(p){let number=0;for(const v of p.versions){v.id??=id();v.number=Number.isInteger(v.number)&&v.number>number?v.number:number+1;number=v.number;}p.versionCounter=Math.max(p.versionCounter||0,number);}
function versionList(p){ensureVersions(p);return `<p class="hint">Збережені стани проєкту · новіші зверху · до 20 версій. Натисніть картку, щоб переглянути, назвати або відновити.</p><div class="versions">${p.versions.length?[...p.versions].reverse().map(v=>{const src=safeImage(v.data.assets?.preview||v.data.assets?.master);return `<button class="version" data-version-id="${esc(v.id)}">${src?`<img src="${src}" alt="">`:icon('file')}<span class="version-info"><strong>v${v.number} · ${esc(versionLabel(v))}</strong><small>${esc(versionTime(v))}</small><small>${esc(versionConcept(v)||'Без обраної концепції')} · ${approvedWithAiRemarks(v.data)?'Погоджено із зауваженнями ШІ':v.data.approved?'Погоджено':'Чернетка'}</small><small>${esc(v.reason||'Раніше збережений стан')}</small></span></button>`;}).join(''):'<span class="hint">Збережіть поточну версію, щоб повернутися до неї пізніше.</span>'}</div>`;}
function saveVersionDialog(p){const concept=p.concepts?.find(c=>c.id===p.selected)?.title;modal(`<div class="dialog-head"><h2>Зберегти версію</h2>${btn('close','Закрити','close')}</div><div class="field"><label for="version-name">Назва, за якою впізнаєте варіант</label><input id="version-name" maxlength="120" value="${esc(concept||p.title)}" placeholder="Наприклад: Лис · широка рамка"></div><p class="hint">Збережуться обидва зображення, концепція, параметри, палітра й правки.</p><div class="dialog-actions"><button class="btn primary" id="confirm-save-version">Зберегти версію</button></div>`);document.querySelector('#confirm-save-version').onclick=async()=>{const label=document.querySelector('#version-name').value.trim();await snapshot(p,true,'Збережено вручну',label);close();render();};}
function openVersion(p,v){const d=v.data;modal(`<div class="dialog-head"><h2>v${v.number} · ${esc(versionLabel(v))}</h2>${btn('close','Закрити','close')}</div><p class="hint">${esc(versionTime(v))} · ${esc(v.reason||'Раніше збережений стан')}</p><div class="version-preview">${['preview','master'].map(k=>{const src=safeImage(d.assets?.[k]);return `<figure>${src?`<img src="${src}" alt="${k==='preview'?'Вигляд виробу':'Декор'}">`:'<p class="hint">Зображення відсутнє</p>'}<figcaption>${k==='preview'?'Вигляд виробу':'Фронтальний декор'}</figcaption></figure>`;}).join('')}</div><p><strong>Концепція:</strong> ${esc(versionConcept(v)||'Не обрана')}<br>${esc(d.type)} · ${d.width} × ${d.height} мм · ${approvedWithAiRemarks(d)?'Погоджено із зауваженнями ШІ':d.approved?'Погоджено':'Чернетка'}</p><p class="hint">${(d.palette||[]).map(k=>esc(colors.find(c=>c.id===k)?.name||k)).join(' · ')}</p>${approvedWithAiRemarks(d)?`<p class="note">Користувач прийняв зауваження ШІ.${d.appearanceApproval.comment?' '+esc(d.appearanceApproval.comment):''}</p>`:''}${d.notes?.length?`<p class="hint">Остання правка: ${esc(d.notes.at(-1))}</p>`:''}<div class="field"><label for="version-label">Назва версії</label><input id="version-label" maxlength="120" value="${esc(versionLabel(v))}"></div><p class="hint">Відновлення поверне цей стан у поточний проєкт. Перед цим поточний стан буде автоматично збережено.</p><div class="dialog-actions"><button class="btn" id="rename-version">Зберегти назву</button><button class="btn primary" id="confirm-restore">Відновити цю версію</button></div>`);document.querySelector('#rename-version').onclick=async()=>{v.label=document.querySelector('#version-label').value.trim().slice(0,120);await persist();close();render();toast('Назву версії збережено');};document.querySelector('#confirm-restore').onclick=async()=>{const data=structuredClone(v.data);p=await editableProject(p,{checkpoint:false});await snapshot(p,false,'Перед відновленням v'+v.number);const history=p.versions,counter=p.versionCounter,origin=p.variantOf;Object.assign(p,{appearanceApproval:null,approvedAt:null,paletteConfirmation:null,route:null,resultDraft:null},data,{id:p.id,versions:history,versionCounter:counter,aiJob:null,...origin?{variantOf:origin,approved:false,appearanceApproval:null,approvedAt:null}:{}});p.updatedAt=date();await persist();close();render();toast('Відновлено v'+v.number+' · '+versionLabel(v));};}
async function snapshot(p,notify=true,reason='Автоматичне збереження перед зміною',label=''){ensureRoute(p);ensureVersions(p);const {versions,aiJob,versionCounter,...data}=p;p.versionCounter++;p.versions.push({id:id(),number:p.versionCounter,label:label.slice(0,120),reason,savedAt:date(),data:structuredClone(data)});if(p.versions.length>20)p.versions.shift();await persist();if(notify)toast('Версію збережено у цьому браузері');}
document.addEventListener('click',async e=>{const el=e.target.closest('button,a[data-action]');if(!el)return;try{if(el.dataset.action){await handle(el.dataset.action);return;}if(el.dataset.page){page=el.dataset.page;render();return;}let p=current();if(el.dataset.view){view=el.dataset.view;render();}if(el.dataset.color){const choice=paletteChoice(p,el.dataset.color);if(choice.error){toast(choice.error);return;}p=await editableProject(p);p.palette=choice.palette;p.paletteConfirmation=null;sourceChanged(p);render();}if(el.dataset.concept){if(['running','queued'].includes(p.aiJob?.status)||p.selected===el.dataset.concept)return;const chosen=p.concepts.find(c=>c.id===el.dataset.concept),issue=conceptIssue(p,chosen);if(issue){toast(issue);return;}p=await editableProject(p,{mode:'concepts'});if(selectConcept(p,el.dataset.concept)){markOutdated(p);touch(p);render();}}if(el.dataset.open){state.active=el.dataset.open;page='studio';view='preview';await persist();render();}if(el.dataset.filter){filter=el.dataset.filter;render();}if(el.dataset.kb){knowledgeTab=el.dataset.kb;render();}if(el.dataset.step){if(moveToRoute(p,el.dataset.step)){await persist();render();}else toast(routeHints[el.dataset.step]||'Цей крок поки недоступний.');}if(el.dataset.versionId){const v=p.versions.find(v=>v.id===el.dataset.versionId);if(v)openVersion(p,v);}if(el.dataset.delete){const pid=el.dataset.delete;modal(`<h2>Видалити проєкт?</h2><p>Він і локальні версії будуть видалені з цього браузера. Для резервної копії спочатку експортуйте JSON.</p><div class="dialog-actions">${btn('close','Скасувати')}<button id="confirm-delete" class="btn danger">Видалити</button></div>`);document.querySelector('#confirm-delete').onclick=async()=>{state.projects=state.projects.filter(x=>x.id!==pid);if(state.active===pid)state.active=state.projects[0]?.id||null;await persist();close();render();};}if(el.dataset.download){const src=p.assets[el.dataset.download];if(src){const a=document.createElement('a');a.href=safeImage(src);a.download=`${p.id}-${el.dataset.download}.png`;a.click();}}}catch(err){console.error(err);toast('Не вдалося виконати дію. Ваш проєкт залишився доступним.');}});
document.addEventListener('submit',async e=>{if(e.target.id!=='new-form')return;e.preventDefault();const f=new FormData(e.target),p=seed('magnolia');Object.assign(p,{id:id(),title:String(f.get('title')).trim(),type:String(f.get('type')),width:Number(f.get('width')),height:Number(f.get('height')),brief:String(f.get('brief')).trim(),example:null,prepared:false,assets:{preview:null,master:null}});if(!p.title||!validateForm(p))return;state.projects.unshift(p);state.active=p.id;page='studio';await persist();close();render();});
document.addEventListener('change',async e=>{const el=e.target;let p=current();if(el.id==='use-ai-findings'){p.resultDraft={...p.resultDraft,includeFindings:el.checked};await persist();return;}if(el.dataset.field){const value=['width','height','layers'].includes(el.dataset.field)?Number(el.value):el.value;if(p[el.dataset.field]===value)return;const original=p;p=await editableProject(p);p[el.dataset.field]=value;if(el.dataset.field==='layers')p.paletteConfirmation=null;if(el.dataset.field==='layers'&&p.layers===1){p.palette=[p.palette[0]];p.frame='engraved';}sourceChanged(p);if(p!==original||['layers','type','clockMount'].includes(el.dataset.field))render();else refreshProjectContext();if(p.assets.preview)toast('Параметри завдання оновлено. Зображення не перегенеровувалось.');}if(el.dataset.review){p=await editableProject(p,{checkpoint:false});p.reviews[el.dataset.review]=el.value;p.approved=false;touch(p);render();}if(el.dataset.lock){p=await editableProject(p);if(el.checked)p.locks.push(el.dataset.lock);else p.locks=p.locks.filter(x=>x!==el.dataset.lock);touch(p);render();}if(el.dataset.upload){const file=el.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8*1024*1024){toast('Додайте PNG, JPG або WebP до 8 МБ.');return;}const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});if(current()!==p)return;p=await editableProject(p);if(el.dataset.upload==='reference'){p.reference=data;markSourceChanged(p);markOutdated(p);}else{await snapshot(p,false,'Перед заміною зображення');p.assets[el.dataset.upload]=data;if(p.variantOf)p.variantOf.inheritedImages=false;p.pendingAssetsUpdate=(p.pendingAssetsUpdate||[]).filter(x=>x!==el.dataset.upload);p.example=null;p.aiReport=null;p.reviews={engraving:'unknown',palette:'unknown',parts:'unknown',composition:'unknown'};}touch(p);render();toast('Зображення додано. Перевірку не виконано автоматично.');}});
document.addEventListener('toggle',e=>{if(e.target.id==='result-corrections'){const p=current();if(p){p.resultDraft={...p.resultDraft,open:e.target.open};persist();}}},true);
document.addEventListener('input',e=>{if(e.target.id==='change-note'){const p=current();if(p){p.resultDraft={...p.resultDraft,text:e.target.value.slice(0,4000)};persist();}return;}if(e.target.id==='search'){const pos=e.target.selectionStart;search=e.target.value;render();const x=document.querySelector('#search');x.focus();x.setSelectionRange(pos,pos);}});
function normalizeImported(x,history=true){
  if(!x||typeof x.title!=='string'||typeof x.brief!=='string'||!TYPES.includes(x.type)||!Number.isFinite(x.width)||!Number.isFinite(x.height)||x.width<20||x.height<20||!((x.width<=300&&x.height<=400)||(x.width<=400&&x.height<=300)))throw Error('fields');
  if(!Array.isArray(x.palette)||!x.palette.length||new Set(x.palette).size!==x.palette.length||x.palette.some(k=>!colors.some(c=>c.id===k))||x.palette.length>4||(x.palette.length===4&&!x.palette.includes('black')))throw Error('palette');
  if(!x.assets||['preview','master'].some(k=>x.assets[k]!==null&&x.assets[k]!==undefined&&!safeImage(x.assets[k]))||(x.reference&&!safeImage(x.reference)))throw Error('images');
  const p=seed('magnolia');Object.assign(p,{id:id(),title:x.title.slice(0,100),brief:x.brief.slice(0,4000),type:x.type,clockMount:['wall','stand','unspecified'].includes(x.clockMount)?x.clockMount:'unspecified',width:x.width,height:x.height,palette:[...x.palette],frame:['engraved','cut','none'].includes(x.frame)?x.frame:'engraved',layers:x.layers===1?1:2,example:Object.hasOwn(kinds,x.example)?x.example:null,assets:{preview:x.assets.preview||null,master:x.assets.master||null},reference:x.reference||null,notes:Array.isArray(x.notes)?x.notes.filter(n=>typeof n==='string').slice(0,100).map(n=>n.slice(0,4000)):[],locks:Array.isArray(x.locks)?x.locks.filter(n=>typeof n==='string').slice(0,20).map(n=>n.slice(0,200)):[],concepts:[],selected:null,prepared:true,approved:false,pendingAssetsUpdate:Array.isArray(x.pendingAssetsUpdate)?x.pendingAssetsUpdate.filter(k=>['preview','master'].includes(k)):[],versions:[]});
  Object.assign(p,importedConceptSelection(x,colors.map(c=>c.id)));
  p.conceptSetOutdated=x.conceptSetOutdated===true;
  if(x.variantOf&&typeof x.variantOf.projectId==='string'&&typeof x.variantOf.title==='string')p.variantOf={projectId:x.variantOf.projectId.slice(0,100),title:x.variantOf.title.slice(0,120),rootId:String(x.variantOf.rootId||x.variantOf.projectId).slice(0,100),rootTitle:String(x.variantOf.rootTitle||x.variantOf.title).slice(0,120),number:Number.isInteger(x.variantOf.number)&&x.variantOf.number>0?x.variantOf.number:1,inheritedImages:x.variantOf.inheritedImages===true};
  if(x.resultDraft&&typeof x.resultDraft==='object')p.resultDraft={text:typeof x.resultDraft.text==='string'?x.resultDraft.text.slice(0,4000):'',includeFindings:x.resultDraft.includeFindings===true,open:x.resultDraft.open===true};
  if([1,2].includes(x.route?.version))p.route={version:x.route.version,current:x.route.current};
  ensureRoute(p);
  if(x.aiData&&typeof x.aiData==='object')p.aiData=structuredClone(x.aiData);
  if(p.layers===1&&(p.palette.length!==1||p.frame==='cut'))throw Error('layers');
  if(history){if(!Array.isArray(x.versions)||x.versions.length>20)throw Error('versions');p.versions=x.versions.map(v=>{if(!v||!v.data)throw Error('version');return {id:id(),number:Number.isInteger(v.number)&&v.number>0?v.number:undefined,label:typeof v.label==='string'?v.label.slice(0,120):'',reason:typeof v.reason==='string'?v.reason.slice(0,200):'',savedAt:Number.isNaN(Date.parse(v.savedAt))?date():v.savedAt,data:normalizeImported(v.data,false)};});}
  return p;
}
document.querySelector('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>60*1024*1024)throw Error('size');const d=JSON.parse(await file.text());if(d.format!=='plywood-flow-project'||d.version!==1)throw Error('format');const p=normalizeImported(d.project);state.projects.unshift(p);state.active=p.id;page='studio';await persist();render();toast('Імпортовано. Погодження й перевірки потрібно виконати заново.');}catch{toast('Файл не є коректним експортом Plywood Flow або містить неприпустимі дані.');}finally{e.target.value='';}});
const typeCatalog=createTypeCatalog({esc,modal,close,render,toast,download,onChange:async(catalog,changedType,previous)=>{TYPES=catalog.types.map(t=>t.name);const changed=new Set(catalog.types.filter(t=>previous?.types.some(old=>old.id===t.id&&old.revision!==t.revision)).map(t=>t.name));if(changedType)changed.add(changedType);for(const p of state.projects.filter(p=>changed.has(p.type))){markOutdated(p);touch(p);}await persist();}});
TYPES=(await typeCatalog.load()).types.map(t=>t.name);
const paletteConfirmation=createPaletteConfirmation({colors,esc,modal,dialog,close,current,persist,render,onChange:p=>{sourceChanged(p);}});
const appearanceApproval=createApproval({esc,modal,close,toast,persist,snapshot,render,getTypeRevision:p=>typeCatalog.find(p.type)?.revision});
const ai=createAI({prepareStart:async(p,action)=>{if(action==='generate'&&!await confirmGeneration(p))return null;return editableProject(p,{mode:action==='concepts'?'concepts':'parameters',checkpoint:false});},refreshContext:refreshProjectContext,onImagesApplied:(p,assets)=>{if(p.variantOf)p.variantOf.inheritedImages=false;if(current()===p)view=assets.preview?'preview':'master';},confirmPalette:p=>paletteConfirmation.ensure(p),paletteSummary:p=>paletteConfirmation.summary(p),getTypeRevision:p=>typeCatalog.find(p.type)?.revision||0,current,projects:()=>state.projects,persist,snapshot,render,toast,esc,validate:validateForm});
let loadedState;
try{
  db=await openDB();loadedState=await readDB();
  if(loadedState!==undefined){
    const migration=migrateStoredState(loadedState);state=migration.state;
    if(migration.migrated)await writeAppState(db,state,{backup:loadedState});
  }else{
    state={schemaVersion:STATE_VERSION,projects:['magnolia','tits','bird'].map(seed),active:null};state.active=state.projects[0].id;
  }
}catch(error){
  db=null;
  if(loadedState===undefined){state={schemaVersion:STATE_VERSION,projects:['magnolia','tits','bird'].map(seed),active:null};state.active=state.projects[0].id;}
  toast(loadedState===undefined?'Локальне збереження недоступне. Експортуйте проєкти перед закриттям.':'Оновлення сховища не завершено. Початкові дані не перезаписано. '+error.message);
}
for(const p of state.projects){const recorded=p.aiData?.knowledge?.productType;if(recorded&&typeCatalog.find(p.type)?.revision!==recorded.revision)markOutdated(p);ensureRoute(p);}
await persist();
render();

await ai.init();

window.matchMedia('(max-width: 1000px)').addEventListener('change',e=>{for(const item of document.querySelectorAll('.route-disclosure,.context-disclosure'))item.open=!e.matches;});
